using System.ComponentModel.DataAnnotations;using System.ComponentModel.DataAnnotations.Schema;
namespace BarIceCreamShop.Api.Models;
[Table("clientes")]public class Customer{[Column("id_cliente")]public int Id{get;set;}[Column("id_empresa")]public int CompanyId{get;set;}[Column("codigo")]public int Code{get;set;}[Column("nombre")]public string Name{get;set;}="";[Column("lista_precios")]public string PriceList{get;set;}="Predeterminada";[Column("condicion_iva")]public string VatCondition{get;set;}="Consumidor Final";[Column("tipo_documento")]public string DocumentType{get;set;}="DNI";[Column("numero_documento")]public string? DocumentNumber{get;set;}[Column("telefono")]public string? Phone{get;set;}[Column("email")]public string? Email{get;set;}[Column("cumpleanos")]public DateOnly? Birthday{get;set;}[Column("activo")]public bool Active{get;set;}=true;[Column("fecha_creacion")]public DateTime CreatedAt{get;set;}[Column("fecha_modificacion")]public DateTime UpdatedAt{get;set;}}
[Table("cliente_contadores")]public class CustomerCounter{[Column("id_empresa")]public int CompanyId{get;set;}[Column("ultimo_codigo")]public int LastCode{get;set;}}
public class CustomerRequest{[Required,MaxLength(200)]public string Name{get;set;}="";[Required,MaxLength(100)]public string PriceList{get;set;}="Predeterminada";[Required,MaxLength(100)]public string VatCondition{get;set;}="Consumidor Final";[Required,MaxLength(30)]public string DocumentType{get;set;}="DNI";[MaxLength(30)]public string? DocumentNumber{get;set;}[MaxLength(50)]public string? Phone{get;set;}[EmailAddress,MaxLength(200)]public string? Email{get;set;}public DateOnly? Birthday{get;set;}public bool Active{get;set;}=true;}
public record CustomerDto(int Id,int Code,string Name,string PriceList,string VatCondition,string DocumentType,string? DocumentNumber,string? Phone,string? Email,DateOnly? Birthday,bool Active);
